create table RB_LIMIT_SUM_INFO (LIMIT_SUM_CONTENT VARCHAR(500) null  ,EFFECT_DATE TIMESTAMP(3) null  ,CHECK_OBJ_VAL VARCHAR(50) not null  ,EXPIRE_DATE TIMESTAMP(3) null  ,LIMIT_SUM_AMT DECIMAL(38,2) null  ,否 INT null  ,CLIENT_NO VARCHAR(22) not null  ,CREATE_TIMESTAMP VARCHAR(26) not null  ,PRE_REFERENCE VARCHAR(60) null  ,LIMIT_SCENE_NO VARCHAR(50) not null  ,TRAN_CCY VARCHAR(3) null  ,REFERENCE VARCHAR(60) not null  ,LAST_UPD_TIMESTAMP VARCHAR(26) not null  , primary key(CHECK_OBJ_VAL,LIMIT_SCENE_NO));